import kotlin.math.abs
import kotlin.math.max
import kotlin.math.min

fun main() {
    val (L, R, C) = readLine()!!.split(" ").map { it.toInt() }

    if (abs(L - R) >= C) {
        println((min(max(L, R), min(L, R) + C)) * 2)
    } else {
        var l = L
        var r = R
        var c = C
        val diff = abs(l - r)
        if (l > r) {
            r += diff
        } else {
            l += diff
        }
        c -= diff
        println((c / 2 + l) * 2)
    }
}

import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val L = scanner.nextLong()
    val R = scanner.nextLong()
    val C = scanner.nextLong()

    val diff = Math.abs(L - R)
    if (diff >= C) {
        val maxVal = Math.max(L, R)
        val minVal = Math.min(L, R)
        println(Math.min(maxVal, minVal + C) * 2)
    } else {
        val maxVal = Math.max(L, R)
        val remaining = C - diff
        println((maxVal + remaining / 2) * 2)
    }
}

